 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    pts=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c]]
    if len(pts)!=2:return g
    (r1,c1,v1),(r2,c2,v2)=pts
    dr=(r2>r1)-(r2<r1);dc=(c2>c1)-(c2<c1)
    # Axis-aligned pair: mark the gap and continue from each marker away.
    if r1==r2:
        for c in range(min(c1,c2)+1,max(c1,c2)):
            if g[r1][c]==0:g[r1][c]=5
        for r,c,v,sgn in [(r1,c1,v1,-dc),(r2,c2,v2,dc)]:
            x=c+sgn
            while 0<=x<w:
                if g[r][x]==0:g[r][x]=5
                x+=sgn
    elif c1==c2:
        for r in range(min(r1,r2)+1,max(r1,r2)):
            if g[r][c1]==0:g[r][c1]=5
        for r,c,v,sgn in [(r1,c1,v1,-dr),(r2,c2,v2,dr)]:
            x=r+sgn
            while 0<=x<h:
                if g[x][c]==0:g[x][c]=5
                x+=sgn
    else:
        # Diagonal: join the markers using color 5, then extend the ray
        # from the lower/right endpoint in the opposite diagonal color 4.
        r,c=r1,c1
        for _ in range(max(abs(r2-r1),abs(c2-c1))-1):
            r+=dr;c+=dc
            if g[r][c]==0:g[r][c]=5
        for sign in (-1,):
            r,c=r2+sign*dr,c2+sign*dc
            while 0<=r<h and 0<=c<w:
                if g[r][c]==0:g[r][c]=4
                r+=sign*dr;c+=sign*dc
        # color 3 sits on diagonal intersection in demonstrated pattern
        if 0<=r2-dr<h and 0<=c2-dc<w and g[r2-dr][c2-dc]==0:g[r2-dr][c2-dc]=3
    return g
"
