    done=set()
    for color, ps in groups.items():
        if len(ps)!=2: continue
        (r1,c1),(r2,c2)=ps
        if r1==r2:
            lo,hi=sorted((c1,c2))
            for c in range(lo+1,hi):
                if g[r1][c]==0:g[r1][c]=5
            for c in range(lo-1,0,-1):
                if g[r1][c]==0:g[r1][c]=5
            if lo-1>=0 and g[r1][lo-1]==0:g[r1][lo-1]=color
            for c in range(hi+1,w):
                if g[r1][c]==0:g[r1][c]=5
            if hi+1<w and g[r1][hi+1]==0:g[r1][hi+1]=color
        elif c1==c2:
            lo,hi=sorted((r1,r2))
