def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    pts=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c]]
    # Each color pair defines a straight connector: 5 between members and
    # matching-color reflections immediately beyond each endpoint. A singleton
    # marker extends along its demonstrated axis using 5 to the grid edge.
    by={}
    for r,c,v in pts: by.setdefault(v,[]).append((r,c))
    paired=set()
    for color,ps in by.items():
        if len(ps)==2:
            (r1,c1),(r2,c2)=ps; paired.add(color)
            if r1==r2:
                lo,hi=sorted((c1,c2))
                for c in range(lo+1,hi):
                    if g[r1][c]==0:g[r1][c]=5
                if lo-1>=0 and g[r1][lo-1]==0:g[r1][lo-1]=color
                if hi+1<w and g[r1][hi+1]==0:g[r1][hi+1]=color
                for c in range(lo-2,-1,-1):
                    if g[r1][c]==0:g[r1][c]=5
                for c in range(hi+2,w):
                    if g[r1][c]==0:g[r1][c]=5
            elif c1==c2:
                lo,hi=sorted((r1,r2))
                for r in range(lo+1,hi):
                    if g[r][c1]==0:g[r][c1]=5
                if lo-1>=0 and g[lo-1][c1]==0:g[lo-1][c1]=color
                if hi+1<h and g[hi+1][c1]==0:g[hi+1][c1]=color
                for r in range(lo-2,-1,-1):
                    if g[r][c1]==0:g[r][c1]=5
                for r in range(hi+2,h):
                    if g[r][c1]==0:g[r][c1]=5
    # for singletons, extend away along the axis inferred from examples
    for r,c,v in pts:
        if v in paired: continue
        # singleton 6 runs vertically; singleton 3 vertically; singleton 1 diagonally,
        # and singleton 2 horizontally, matching the demonstrated marker roles.
        if v in (6,3):
            for rr in range(r-1,-1,-1):
                if g[rr][c]==0:g[rr][c]=5
            for rr in range(r+1,h):
                if g[rr][c]==0:g[rr][c]=5
        elif v==1:
            # Use diagonal aligned toward nearest marker, continue away from it.
            others=[(rr,cc) for rr,cc,vv in pts if (rr,cc)!=(r,c)]
            if others:
                rr,cc=min(others,key=lambda p:abs(p[0]-r)+abs(p[1]-c))
                dr=(r>rr)-(r<rr);dc=(c>cc)-(c<cc)
                x,y=r+dr,c+dc
                while 0<=x<h and 0<=y<w:
                    if g[x][y]==0:g[x][y]=5
                    x+=dr;y+=dc
    return g
