 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    pts=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    # Pair each marker with its nearest different-color marker. Connect each pair
    # along a straight row/column or diagonal; rays continue from endpoints.
    unused=set(range(len(pts)))
    pairs=[]
    while len(unused)>=2:
        i=min(unused);unused.remove(i)
        r,c,v=pts[i]
        j=min(unused,key=lambda k:(abs(pts[k][0]-r)+abs(pts[k][1]-c),k))
        unused.remove(j);pairs.append((pts[i],pts[j]))
    for (r1,c1,v1),(r2,c2,v2) in pairs:
        dr=(r2>r1)-(r2<r1);dc=(c2>c1)-(c2<c1)
        if dr==0:
            step=dc
            x=c1+step
            while x!=c2:
                if g[r1][x]==0:g[r1][x]=5
                x+=step
            # extend outward with 5
            for x,st in ((c1-step,-step),(c2+step,step)):
                while 0<=x<w:
                    if g[r1][x]==0:g[r1][x]=5
                    x+=st
        elif dc==0:
            step=dr
            y=r1+step
            while y!=r2:
                if g[y][c1]==0:g[y][c1]=5
                y+=step
            for y,st in ((r1-step,-step),(r2+step,step)):
                while 0<=y<h:
                    if g[y][c1]==0:g[y][c1]=5
                    y+=st
        else:
            n=min(abs(r2-r1),abs(c2-c1))
            for i in range(1,n):
                r,c=r1+dr*i,c1+dc*i
                if g[r][c]==0:g[r][c]=5
    return g
"
}

