 "content": "def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    pts=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    # Pair same-color points when duplicated; otherwise pair nearest points.
    by={}
    for r,c,v in pts:by.setdefault(v,[]).append((r,c))
    pairs=[]
    used=set()
    for color,ps in by.items():
        if len(ps)==2:
            pairs.append((ps[0],ps[1]));used.update(ps)
    rest=[p for p in pts if (p[0],p[1]) not in used]
    while len(rest)>=2:
        a=rest.pop(0)
        j=min(range(len(rest)),key=lambda i:abs(rest[i][0]-a[0])+abs(rest[i][1]-a[1]))
        b=rest.pop(j);pairs.append((a,b))
    for (r1,c1,v1),(r2,c2,v2) in pairs:
        dr=(r2>r1)-(r2<r1);dc=(c2>c1)-(c2<c1)
        if r1==r2:
            lo,hi=sorted((c1,c2))
            for c in range(lo+1,hi):
                if g[r1][c]==0:g[r1][c]=5
            if lo>0 and g[r1][lo-1]==0:g[r1][lo-1]=v2
            if hi+1<w and g[r1][hi+1]==0:g[r1][hi+1]=v1
        elif c1==c2:
            lo,hi=sorted((r1,r2))
            for r in range(lo+1,hi):
                if g[r][c1]==0:g[r][c1]=5
            if lo>0 and g[lo-1][c1]==0:g[lo-1][c1]=v2
            if hi+1<h and g[hi+1][c1]==0:g[hi+1][c1]=v1
        else:
            # Connect diagonal pairs in color 5, retaining all markers.
            n=min(abs(r2-r1),abs(c2-c1))
            for i in range(1,n):
                r,c=r1+dr*i,c1+dc*i
                if g[r][c]==0:g[r][c]=5
    return g
