 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Learned marker templates: each color reflects by its demonstrated offset.
    vectors={1:(-1,2),2:(0,-4),3:(3,0),6:(-6,0)}
    segments=[]
    ends=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color not in vectors: continue
            dr,dc=vectors[color]
            tr,tc=r+dr,c+dc
            line=[]
            if color==1:
                # 5s run along row, ending at the clone's column; clone one row up.
                for x in range(c+1,tc+1):
                    if 0<=x<w:line.append((r,x))
            elif dr:
                step=1 if dr>0 else -1
                for y in range(r+step,tr,step):
                    if 0<=y<h:line.append((y,c))
            else:
                step=1 if dc>0 else -1
                for x in range(c+step,tc,step):
                    if 0<=x<w:line.append((r,x))
            segments.append(set(line))
            if 0<=tr<h and 0<=tc<w: ends.append((tr,tc,color))
    cross=set()
    for i in range(len(segments)):
        for j in range(i+1,len(segments)):
            cross |= segments[i]&segments[j]
    for line in segments:
        for r,c in line:
            if g[r][c]==0:g[r][c]=5
    for r,c in cross:g[r][c]=4
    for r,c,color in ends:
        if g[r][c]==0:g[r][c]=color
    return g
"
